# src_scoped with two files: does R/clean.R see the imports of R/util.R?
# Generated by ../../08-box-caching.R. Run here: Rscript -e 'targets::tar_make()'  (USE_CREW=true for crew)
library(targets)
if (Sys.getenv("USE_CREW") == "true")
  tar_option_set(controller = crew::crew_controller_local(name = "crew", workers = 2, seconds_idle = 10))
tar_option_set(error = "continue")   # every target reports its own outcome

tar_option_set(envir = new.env(parent = globalenv()))
# like tar_source(), but each file gets its own scope: its box::use() imports are seen by that file only
source_scoped <- function(dir = "R", envir = tar_option_get("envir")) {
  for (f in list.files(dir, "\\.[rR]$", full.names = TRUE, recursive = TRUE)) {
    file_env <- new.env(parent = envir)
    sys.source(f, envir = file_env, keep.source = FALSE)
    list2env(as.list(file_env), envir)
  }
}
source_scoped()

list(
  tar_target(raw, data.frame(var1 = 1:3)),
  tar_target(out_x, add_x(raw)),
  tar_target(out_y, add_y(raw)),
  tar_target(own_import, count_ids(raw$var1)),
  tar_target(other_files_import, tryCatch(leaky(raw), error = \(e) paste("error:", conditionMessage(e))))
)
